from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        # Precompute factorials for quick lookup
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        # Determine the total number of valid alternating permutations
        if n % 2 == 1:
            total_ways = fact[(n + 1) // 2] * fact[n // 2]
        else:
            total_ways = 2 * fact[n // 2] * fact[n // 2]

        # If k is larger than the total possible valid permutations, return empty list
        if k > total_ways:
            return []

        available = list(range(1, n + 1))
        ans = []

        rem_odds = (n + 1) // 2
        rem_evens = n // 2

        # Build the permutation position by position
        for i in range(n):
            for x in available:
                # Check if the chosen number 'x' satisfies the parity constraints
                if i == 0:
                    if n % 2 == 1 and x % 2 == 0:
                        continue  # If n is odd, the sequence must strictly start with an odd number
                else:
                    if x % 2 == ans[-1] % 2:
                        continue  # Parity must alternate with the previous element

                # Calculate the number of ways to complete the permutation if 'x' is placed here
                if x % 2 == 1:
                    ways = fact[rem_odds - 1] * fact[rem_evens]
                else:
                    ways = fact[rem_odds] * fact[rem_evens - 1]

                # If k falls within the 'ways', 'x' is our choice for the current position
                if k <= ways:
                    ans.append(x)
                    available.remove(x)
                    if x % 2 == 1:
                        rem_odds -= 1
                    else:
                        rem_evens -= 1
                    break
                else:
                    # Otherwise, skip these 'ways' permutations and check the next valid number
                    k -= ways

        return ans

